type AppShellProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 导航数据：一级导航 + 二级（工作区）侧栏，见 nav-config.ts */
  nav: NavConfig
  /** 品牌区：名称、Logo、说明与跳转地址 */
  brand?: AppShellBrand
  /** 顶栏右侧的额外操作区，例如「AI 助手」按钮、服务状态 */
  headerActions?: React.ReactNode
