    props: mergeProps<"div">(
      {
        className: cn(
          "flex w-full items-center gap-3 rounded-md bg-muted/50 px-3 py-2 text-left transition-colors outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
          render && "hover:bg-muted",
